import threading
import sys


class Thread(threading.Thread):
    """
    Thread to be used to catch message from background process
    """
    def __init__(self, alias, exc_callback, target, args=None):
        threading.Thread.__init__(self, target=target, args=args)
        self.__alias = alias
        self.__target = target
        self.__args = args
        self.__exc_callback = exc_callback

    def run(self):
        """ Override for run function in threading.Thread """
        try:
            if self.__target:
                self.__target(*self.__args)
        except Exception as e:
            self.__exc_callback(self.__alias, sys.exc_info())
        finally:
            del self.__target, self.__args
